    ++offset;

    nbytes = write(p[1], data, data_size);
    if (nbytes < 0){perror("write");return 1;}
    if (nbytes < data_size){fprintf(stderr,"short write\n");return 1;}

    fprintf(stderr,"It worked! wrote %ld bytes at offset %lld\n",(long)nbytes,(long long)(offset));
